/* Static PWA verification: manifest fields + icon files + the generated
 * Workbox service worker (public/sw.js). Run after `npm run build` (the
 * service worker is generated by scripts/build-sw.mjs). */
import fs from "node:fs";

const fail = (msg) => {
  console.error("FAIL:", msg);
  process.exit(1);
};

// 1. Manifest
const m = JSON.parse(fs.readFileSync("public/manifest.json", "utf8"));
const required = ["short_name", "name", "start_url", "display", "theme_color", "background_color", "icons"];
for (const k of required) {
  if (!(k in m)) fail(`manifest missing field "${k}"`);
}
console.log("manifest fields OK:", required.join(", "));
if (m.display !== "standalone") fail(`display must be standalone, got ${m.display}`);
if (m.start_url !== "/dashboard") fail("start_url must be /dashboard");

const sizes = m.icons.map((i) => `${i.sizes}/${i.purpose}`).join(", ");
console.log("icons declared:", sizes);
for (const i of m.icons) {
  const p = "public" + i.src;
  if (!fs.existsSync(p)) fail(`icon file missing: ${p}`);
  console.log("  exists:", i.src);
}
console.log("ALL ICONS PRESENT");

// 2. Generated service worker
const SW = "public/sw.js";
if (!fs.existsSync(SW)) {
  fail(`${SW} not found — run \`npm run build\` first (build-sw.mjs generates it)`);
}
const sw = fs.readFileSync(SW, "utf8");

// Workbox runtime is self-hosted (no CDN dependency) and imported.
if (!sw.includes("importScripts(")) fail("sw.js does not self-host the Workbox runtime");
for (const mod of ["workbox-core.prod.js", "workbox-routing.prod.js", "workbox-strategies.prod.js", "workbox-precaching.prod.js"]) {
  if (!fs.existsSync(`public/workbox/${mod}`)) fail(`workbox runtime file missing: public/workbox/${mod}`);
  if (!sw.includes(`"/workbox/${mod}"`)) fail(`sw.js does not import /workbox/${mod}`);
}
console.log("workbox runtime self-hosted OK (core/routing/strategies/precaching)");

// The precache manifest is injected into the source; assert the public shell
// URLs are present as quoted manifest entries.
const SHELL = ["/", "/resources", "/resources/exercises", "/offline"];
for (const u of SHELL) {
  if (!sw.includes(`"${u}"`)) fail(`precache manifest missing URL "${u}"`);
}
console.log("shell URLs in precache manifest:", SHELL.join(", "));

// Auth-gated routes must not be precached (would cache the login page under
// the protected URL on a logged-out install).
if (sw.includes('"/dashboard"')) fail('"/dashboard" must NOT be precached (auth-gated)');

// Offline fallback wiring.
if (!sw.includes('request.mode === "navigate"')) fail("navigation handler missing");
if (!sw.includes('caches.match("/offline"')) fail("/offline fallback wiring missing");

console.log("sw.js: workbox precache correct, offline fallback wired");
console.log("\nALL STATIC PWA CHECKS PASSED");
